import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五百三十五章 不同的法语与法门","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/535第五百三十五章 不同的法语与法门.md","filePath":"meditation/巴利文大藏经/535第五百三十五章 不同的法语与法门.md"}'),o={name:"meditation/巴利文大藏经/535第五百三十五章 不同的法语与法门.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第五百三十五章-不同的法语与法门" tabindex="-1">第五百三十五章 不同的法语与法门 <a class="header-anchor" href="#第五百三十五章-不同的法语与法门" aria-label="Permalink to &quot;第五百三十五章 不同的法语与法门&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部41相应7经/牛达多经(质多相应/处篇/弟子记说)</p><p>有个时候，牛达多尊者住在摩叉止陀山的安婆陀伽林中，有一天，质多居士来到牛达多尊者的住处，他顶礼牛达多尊者后，就在一旁坐下，牛达多尊者对质多居士说：“质多居士，无量心解脱、无所有心解脱、空心解脱、无相心解脱，这些法语说的到底是什么意思呢？这些法语用不同的词语，讲的是不同的意思，还是说的是相同的意思，只是用的词语不同而已。质多居士，也就是说：这些法语到底讲的是同一个意思，还是讲的是不同的意思？”</p><p>质多居士说：“牛达多尊者，有的法语，有的修行法门，它们用不同的词语指代不同的含义，讲说不同的法义，但是，有一些法语，有一些修行法门，它们用不同的词语指代相同的含义，讲说相同的法义。”</p><p>牛达多尊者，哪些法语，哪些修行法门，它们是用不同的词语指代不同的含义，讲说不同的法义呢？修行人身体行为做善事，口说善语，内心生起善念，用帮助救济世间人或众生的善行、慈悲心布满他来到的一个地方后，再这样用同样帮助救济世间人或众生的善行、慈悲心布满他来到的第二个地方、第三个地方、第四个地方、上方、下方，也就是将他帮助救济世间人或众生的善行、慈悲心布满东南西北方向，布满东南、西南、西北、东北方向，布满上方、下方，布满世间的一切地方，将广大无量的慈悲心布满世间，将包容世间一切人或众生的心布满世间，将对世间一切人或众生没有怨恨，没有恶意的心布满世间。对世间一切的人或众生都一视同仁慈悲的帮助和救济。以这样大慈悲的心安住在世间，由此生起慈悲帮助救济众生的欢喜心，之后将慈悲欢喜心平息归于宁静，帮助救济世间人或众生的时候，虽然有善行、善言、善念的生起，但是不会因此生起欢喜心，不会生起快乐、喜悦，因为修行人明白：快乐、喜悦等等欢喜心仍然是烦恼，修行人内心平静、宁静的帮助救助世间人或众生不求回报，他的善行、善言、善念布满他来到的第一个地方，又布满他来到的第二个地方、第三个地方、第四个地方、上方、下方，也就是将他帮助救济世间人或众生的善行、善言、善念平静的布满东南西北方向，平静的布满东南、西南、西北、东北方向，平静的布满上方、下方，平静的布满世间的一切地方，将广大无量的善行、善言、善念平静的布满世间，将包容世间一切人或众生的心布满世间，将对世间一切人或众生没有怨恨，没有恶意的心布满世间。一视同仁慈悲的帮助和救济世间一切人或众生的时候，修行人内心平静安宁不会生起喜悦、快乐、欢喜的心，不求回报。牛达多尊者这就被称为无量心解脱，也就是：以广大无量的善心布满世间、不求回报而获得解脱，就是无量心解脱。</p><p>牛达多尊者，什么是无所有心解脱呢？当修行人超越识无边处境界后，证悟明白：「世间一切事物随时都在变化，无法永远存在，无法永恒保持不变，无法永远拥有，世间一切的事物会衰败、灭亡、消失，实际上什么都没有」由此观想「世间什么都没有」，不再执着和挂念世间的一切事物，这样就进入了无所有处的境界之中，什么是识无边处境界呢？就是观想：「自己的眼识、耳识、鼻识、舌识、身识、意识如同虚空一样是无边无际的」（眼识、耳识、鼻识、舌识、身识、意识解释，见第一百八十八章）除了这个观想外，不由世间的事物生起念想。牛达多尊者，当只生起「世间什么都没有」念想的时候，不再生起其他念想的时候，这就称为无所有心解脱，也就是由明白世间一切事物是无常的而不再执着和挂念世间的事物，用「世间什么都没有」的念想熄灭、除灭对世间一切事物的贪欲、渴爱、烦恼、痛苦而获得解脱，就是无所有心解脱。</p><p>牛达多尊者，什么是空心解脱呢？当修行人来到山林，或者大树下，或者房屋中等等任何地方，都观想：「我的物质身体，我拥有的物质事物都是空的」什么是空呢？空的意思并不是什么都没有，而是指世间的一切事物无法永远保持相同的状态，世间一切的事物随时在变化，所谓空就是随时在变化，随着时间的推移，世间一切的事物无法保持完全相同的状态。当修行人观想「我的物质身体，我拥有的物质事物都是空的」的时候，就能放下对世间一切事物的执着和挂念获得解脱，这就被称为空心解脱。</p><p>牛达多尊者，什么是无相心解脱呢？修行人不执着和挂念物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想，内心不被它们扰动、影响、污染，修行人不对物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想生起念想，这样就进入无相心三昧，什么是三昧呢？也就是内心不散乱、不混乱，安住在平静、宁静的纯一境界之中，牛达多尊者，这就被称为无相心解脱，也就是由不执着和挂念物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想而获得解脱，就是无相心解脱。</p><p>牛达多尊者，刚才我说的这些法语，说的这些修行方法门，它们就是用不同的词语指代不同的含义，讲说不同的法义。</p><p>牛达多尊者，哪些法语，哪些修行法门，它们用不同的词语指代相同的含义，讲说相同的法义呢？</p><p>牛达多尊者，刚才我说到无量，这个量是什么意思呢？就是测量、衡量的意思，测量、衡量数量的多少，这就是量的意思。贪欲、渴爱就是测量、衡量的制造者、作者，也就是说贪欲、渴爱创造出了测量、衡量。愤怒就是测量、衡量的制造者、作者，也就是说愤怒创造出了测量、衡量。沉迷的愚痴就是测量、衡量的制造者、作者，也就是说沉迷的愚痴创造出了测量、衡量。烦恼和痛苦已经灭尽的修行人，犹如被连根拔起，砍成小木块，被大火焚烧成灰烬，又将灰烬撒到江河之中冲走，已经消失不见、不复存在，在未来也不可能会继续生长的多罗树一样，这些修行人的烦恼和痛苦也如同这棵消失不见的多罗树一样，他们在未来也不会再生起烦恼和痛苦。牛达多尊者，在无量心解脱法门中所达到的不同清净层次里，不动心解脱是其中无上、最高、最清净的层次，是其中第一清净的境界。而这个不动心解脱就是：贪欲、渴爱的熄灭、灭尽、消失，愤怒的熄灭、灭尽、消失，沉迷愚痴的熄灭、灭尽、消失，也就是空掉贪欲、渴爱、愤怒、沉迷愚痴，牛达多尊者，您现在应该明白为什么这个修行方法叫做无量心解脱了吧，所谓无量就是无限的接近于无，无什么呢？就是无贪欲、无渴爱、无愤怒、无沉迷愚痴，那么要无就要先舍，将自己拥有的一切全部用来帮助救济世间人或众生，将自己拥有的一切全部施舍给世间人或众生，甚至于将自己的生命也布施供养给世间人或众生，如此不拥有任何的东西、事物，舍弃一切的东西、事物，自然就熄灭、灭尽了贪欲、渴爱、愤怒、沉迷愚痴，自然就无限接近于无了，所谓无就是，无贪欲、无渴爱、无愤怒、无沉迷愚痴，无量就是无限接近于无贪欲、无渴爱、无愤怒、无沉迷愚痴。</p><p>牛达多尊者，贪欲、渴爱也是件物品、东西，愤怒也是件物品、东西，沉迷愚痴也是件物品、东西。烦恼和痛苦已经灭尽的修行人，犹如被连根拔起，砍成小木块，被大火焚烧成灰烬，又将灰烬撒到江河之中冲走，已经消失不见、不复存在，在未来也不可能会继续生长的多罗树一样，这些修行人的烦恼和痛苦也如同这棵消失不见的多罗树一样，他们在未来也不会再生起烦恼和痛苦。牛达多尊者，在无所有心解脱法门中所达到的不同清净层次里，不动心解脱是其中无上、最高、最清净的层次，是其中第一清净的境界。而这个不动心解脱就是：贪欲、渴爱的熄灭、灭尽、消失，愤怒的熄灭、灭尽、消失，沉迷愚痴的熄灭、灭尽、消失，也就是空掉贪欲、渴爱、愤怒、沉迷愚痴，牛达多尊者，您现在应该明白为什么这个修行方法叫做无所有心解脱了吧，所谓无所有就是不拥有任何的物品、物件，没有任何的物品、物件就不会生起贪欲、渴爱、愤怒、沉迷愚痴，如何做才能不拥有任何的物品、东西呢？不拥有任何的物品、东西就要先舍，将自己拥有的一切物品、东西全部用来帮助救济世间人或众生，将自己拥有的一切物品、东西全部施舍给世间人或众生，甚至于将自己的物质身体也布施供养给世间人或众生，如此不拥有任何的物品、东西，舍弃一切的物品、东西，自然就熄灭、灭尽了贪欲、渴爱、愤怒、沉迷愚痴，自然就不拥有任何的物品、东西了，没有任何的物品、东西，贪欲、渴爱、愤怒、沉迷愚痴自然就灭尽了。</p><p>牛达多尊者，刚才我说到无相，这个相是什么意思呢？就是执着和挂念物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想，由物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想生起念想，内心被物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想扰动、影响、污染。贪欲、渴爱就是相的制造者、作者，也就是说贪欲、渴爱创造出了相。愤怒就是相的制造者、作者，也就是说愤怒创造出了相。沉迷的愚痴就是相的制造者、作者，也就是说沉迷的愚痴创造出了相。烦恼和痛苦已经灭尽的修行人，犹如被连根拔起，砍成小木块，被大火焚烧成灰烬，又将灰烬撒到江河之中冲走，已经消失不见、不复存在，在未来也不可能会继续生长的多罗树一样，这些修行人的烦恼和痛苦也如同这棵消失不见的多罗树一样，他们在未来也不会再生起烦恼和痛苦。</p><p>牛达多尊者，在无相心解脱法门中所达到的不同清净层次里，不动心解脱是其中无上、最高、最清净的层次，是其中第一清净的境界。而这个不动心解脱就是：贪欲、渴爱的熄灭、灭尽、消失，愤怒的熄灭、灭尽、消失，沉迷愚痴的熄灭、灭尽、消失，也就是空掉贪欲、渴爱、愤怒、沉迷愚痴，牛达多尊者，您现在应该明白为什么这个修行方法叫做无相心解脱了吧，所谓无相就是无限接近于不执着和挂念物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想的境界，无限性接近于不对物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想生起念想的境界，这样内心就不会被物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想扰动、影响、污染，也就是无限接近于无贪欲、无渴爱、无愤怒、无沉迷愚痴的境界，那么要无就要先舍，将自己拥有的一切全部用来帮助救济世间人或众生，将自己拥有的一切全部施舍给世间人或众生，甚至于将自己的物质身体、生命也布施供养给世间人或众生，如此不拥有任何的东西、事物，舍弃一切的东西、事物，自然就熄灭、灭尽了贪欲、渴爱、愤怒、沉迷愚痴，自然就无限接近于不执着和挂念物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想的境界，自然无限性接近于不对物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想生起念想的境界了，自然内心就不会被物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想扰动、影响、污染了，所谓无就是无贪欲、无渴爱、无愤怒、无沉迷愚痴，无相就是无限接近于不执着和挂念物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想的境界，无限性接近于不对物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想生起念想的境界，这样内心就不会被物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想扰动、影响、污染。</p><p>牛达多尊者，这就是「用不同的词语指代相同的含义，讲说相同法义的法语、修行法门」的意思。”</p><p>牛达多尊者说：“质多居士，我们明白了，原来不同的法语、修行法门，最后达到的修行目标和修行结果是一样的，原来除灭、灭尽贪欲、渴爱、愤怒、沉迷愚痴就是世尊所说全部法语与修行法门的目的，不同的法语、法门虽然切入点不一样，含义不一样，可是最后要达到的结果和效果是一样的，都是为了灭尽烦恼和痛苦。质多居士，您已经完全理解和明白世尊所说正法的法义，您已经睁开了解脱智慧的双眼，感谢您为我解说世尊的正法，我随喜赞叹您说法的无量功德。”</p>',17)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
